// Retrospectiva (MOT-04). Generated by the worker (retro.generate); the app only reads it and marks it seen.
import type { RetroPeriodType, RetroStats } from '@studify/shared';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../../api/supabase';
import { useSession } from '../auth/session';
import { rows } from '../common/query';

export interface Retrospective {
  id: string;
  period_type: RetroPeriodType;
  goal_id: string | null;
  period_start: string;
  period_end: string;
  stats: RetroStats;
  title: string;
  subtitle: string | null;
  generated_at: string;
  seen_at: string | null;
}

const COLUMNS = 'id,period_type,goal_id,period_start,period_end,stats,title,subtitle,generated_at,seen_at';

export function useRetrospectives() {
  const { userId } = useSession();
  return useQuery({
    queryKey: ['retrospectives', userId],
    enabled: !!userId,
    queryFn: () => rows<Retrospective>(supabase.from('retrospectives').select(COLUMNS).eq('user_id', userId!).order('generated_at', { ascending: false }).limit(30)).catch(() => [] as Retrospective[]),
  });
}

export function useRetrospective(id: string | undefined) {
  const list = useRetrospectives();
  return { ...list, data: list.data?.find((r) => r.id === id) ?? null };
}

/** The Hoje banner shows the newest one the student has not opened yet. */
export function useUnseenRetrospective(): Retrospective | null {
  return useRetrospectives().data?.find((r) => !r.seen_at) ?? null;
}

export function useMarkRetroSeen() {
  const qc = useQueryClient();
  const { userId } = useSession();
  return async (id: string) => {
    await supabase.from('retrospectives').update({ seen_at: new Date().toISOString() }).eq('id', id).is('seen_at', null);
    await qc.invalidateQueries({ queryKey: ['retrospectives', userId] });
  };
}
